using System;using System.Text.RegularExpressions;using System.Net;using System.IO;using System.Linq;using System.Text;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
public static class LegacyCandidateReviews {
 static Dictionary<string,object>D(object o){return ManualHypotheses.D(o);}static object V(Dictionary<string,object>d,string k){return ManualHypotheses.V(d,k);}static string S(Dictionary<string,object>d,string k){return ManualHypotheses.S(d,k);}static IEnumerable<Dictionary<string,object>>Items(Dictionary<string,object>d,string k){return ManualHypotheses.A(V(d,k)).Select(D);}static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128};}
 static bool Same(object a,object b){var x=a as Dictionary<string,object>;var y=b as Dictionary<string,object>;if(x!=null&&y!=null)return x.Count==y.Count&&x.All(k=>y.ContainsKey(k.Key)&&Same(k.Value,y[k.Key]));var aa=a as IList;var bb=b as IList;if(aa!=null&&bb!=null)return aa.Count==bb.Count&&Enumerable.Range(0,aa.Count).All(i=>Same(aa[i],bb[i]));return Object.Equals(a,b);}
 static Dictionary<string,object>Read(string p){if(new FileInfo(p).Length>8388608)throw new InvalidDataException("Legacy review exceeds8MiB");return Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(p,Encoding.UTF8));}
 static string RawDocumentText(byte[]raw){string html=new UTF8Encoding(false,true).GetString(raw);html=Regex.Replace(html,@"<!--[\s\S]*?-->"," ");foreach(string tag in new[]{"script","style","nav","footer"})html=Regex.Replace(html,"<"+tag+@"\b[^>]*>[\s\S]*?</"+tag+">"," ",RegexOptions.IgnoreCase);var main=Regex.Match(html,@"<main\b[^>]*>([\s\S]*?)</main>",RegexOptions.IgnoreCase);if(main.Success)html=main.Groups[1].Value;html=Regex.Replace(html,@"<[^>]+>"," ");return Regex.Replace(WebUtility.HtmlDecode(html),@"\s+"," ").Trim();}
 public static string Describe(string root,Dictionary<string,object>selected){string path=Path.Combine(root,"legacy-candidate-reviews.json");if(!File.Exists(path))return "";try{var w=Read(path);string payload=S(w,"payload_json");if(ProvenanceAudit.Sha(payload)!=S(w,"payload_sha256"))throw new InvalidDataException("Legacy review payload hash mismatch");var data=Json().Deserialize<Dictionary<string,object>>(payload);if(S(data,"schema")!="legacy-candidate-evidence-reviews-v1"||!Object.Equals(V(data,"auto_admission"),false))throw new InvalidDataException("Legacy review policy mismatch");string id=S(selected,"candidate_id");var review=Items(data,"reviews").SingleOrDefault(r=>S(r,"candidate_id")==id);if(review==null)return "Для этой сохранённой бизнес-гипотезы ручной разбор не подготовлен. Это не подтверждение её исходных утверждений.\r\n";if(S(review,"origin")!="ASSISTANT_MANUAL_REVIEW_OF_SAVED_EVIDENCE_NOT_MODEL_EXECUTION"||!Object.Equals(V(review,"auto_admission"),false)||S(review,"execution_status")!="PLAN_ONLY_NOT_EXECUTED"||S(review,"customer_status")!="UNVERIFIED")throw new InvalidDataException("Manual candidate plan cannot authorize execution or verify a customer");string snapshot=S(review,"candidate_snapshot_json");if(ProvenanceAudit.Sha(snapshot)!=S(review,"candidate_snapshot_sha256"))throw new InvalidDataException("Candidate reference snapshot hash mismatch");var original=Json().Deserialize<Dictionary<string,object>>(snapshot);if(S(original,"candidate_id")!=id)throw new InvalidDataException("Candidate review belongs to another ID");var actual=ManualHypotheses.A(Json().DeserializeObject(File.ReadAllText(Path.Combine(root,"candidates.json"),Encoding.UTF8))).Select(D).SingleOrDefault(c=>S(c,"candidate_id")==id);bool current=actual!=null&&Same(actual,original);foreach(string field in new[]{"title","buyer","problem_hypothesis","solution_hypothesis","validation_step","observed_basis","review_revision_hash"})if(!Same(V(selected,field),V(original,field)))current=false;var b=new StringBuilder(current?"РУЧНОЙ РАЗБОР ТОЧНОЙ СОХРАНЁННОЙ РЕВИЗИИ — не выполненный AI-анализ\r\n":"ИСТОРИЧЕСКИЙ РУЧНОЙ РАЗБОР: кандидат изменился; план НЕ подтверждает новую ревизию\r\n");b.AppendLine("Подготовлены сопоставление и acceptance-матрица. Тесты/публикации/сообщения не выполнялись; это не разрешение их выполнить.").AppendLine("Клиенты, покупатели, спрос и экономика не подтверждены; пользовательские связи с клиентами не предполагаются.").AppendLine("Снимок кандидата SHA256: "+S(review,"candidate_snapshot_sha256"));var assessment=D(V(review,"assessment"));foreach(var p in new[]{new[]{"alignment","Что поддерживает исходник / что добавлено моделью"},new[]{"alternatives","Ограничения сравнения альтернатив"},new[]{"next_action","Подготовленный план следующей проверки — НЕ выполнен"},new[]{"success","Критерий успеха"},new[]{"failure","Отрицательный результат"},new[]{"market_gap","Пробел до рыночной гипотезы"},new[]{"permission_boundary","Граница исполнения"}})b.AppendLine().AppendLine(p[1]+": "+S(assessment,p[0]));b.AppendLine().AppendLine("МАТРИЦА СОХРАНЁННОГО ОСНОВАНИЯ / НЕИЗВЕСТНОГО");foreach(var row in Items(review,"acceptance_matrix"))b.AppendLine(S(row,"check")+" | "+S(row,"current_status")).AppendLine(S(row,"saved_basis")).AppendLine(S(row,"execution_boundary_or_missing_evidence"));
 foreach(var source in Items(review,"source_references")){if(!Items(original,"observed_basis").Any(r=>S(r,"url")==S(source,"url")&&S(r,"title")==S(source,"saved_title")&&S(r,"evidence_id")==S(source,"evidence_id_local_to_old_card"))||ProvenanceAudit.Sha(S(source,"saved_title"))!=S(source,"saved_title_sha256"))throw new InvalidDataException("Legacy source URL/title/E-ID binding mismatch");b.AppendLine().AppendLine("Исходная ссылка старой карточки: "+S(source,"url")).AppendLine("E-ID только внутри этой карточки: "+S(source,"evidence_id_local_to_old_card")).AppendLine("Сохранённый заголовок (metadata): "+S(source,"saved_title")).AppendLine(S(source,"old_input_scope"));var additional=D(V(source,"additional_saved_original"));if(additional.Count>0){if(S(additional,"url")!=S(source,"url")||!new[]{"original_post","archived_original"}.Contains(S(additional,"kind")))throw new InvalidDataException("Additional original assigned to wrong source/role");EvidenceBindings.Check(root,additional,false);b.AppendLine("ДОПОЛНИТЕЛЬНО СОХРАНЁННЫЙ ОРИГИНАЛ — не подменяет вход старой модели").AppendLine("Получено: "+EvidenceDates.Display(V(additional,"captured_at"))+" | автор: "+S(additional,"author")).AppendLine("SHA256 текста: "+S(additional,"text_sha256")).AppendLine(S(additional,"text"));}else b.AppendLine("Полное исходное тело сейчас недоступно локально; заголовок/ответ/другой E-ID его не заменяют.");}
 foreach(var doc in Items(review,"documents")){b.AppendLine().AppendLine("Документ: "+S(doc,"url")+" | уровень: "+S(doc,"body_evidence"));var body=D(V(doc,"preserved_snapshot"));if(body.Count>0){if(S(body,"url")!=S(doc,"url")||S(body,"kind")!="provider_document")throw new InvalidDataException("Document snapshot assigned to wrong URL/role");if(S(body,"raw_local_relative")!=""){string name=S(body,"raw_local_relative");if(!Regex.IsMatch(S(body,"response_sha256"),"^[0-9a-f]{64}$")||name!="direct-source-payloads/"+S(body,"response_sha256")+".raw")throw new InvalidDataException("Unexpected raw evidence path");var oldRecord=Items(D(V(original,"direct_alternatives")),"alternatives").SingleOrDefault(r=>S(r,"source_url")==S(doc,"url"));if(oldRecord==null||S(oldRecord,"response_sha256")!=S(body,"response_sha256")||S(oldRecord,"observed_at")!=S(body,"captured_at")||S(oldRecord,"provider")!=S(body,"author"))throw new InvalidDataException("Restored source differs from frozen candidate document record");string rawpath=Path.Combine(root,name);if(File.Exists(rawpath)){if(new FileInfo(rawpath).Length>4194304||!LocalResearchController.Hash(rawpath).Equals(S(body,"response_sha256"),StringComparison.OrdinalIgnoreCase)||RawDocumentText(File.ReadAllBytes(rawpath))!=S(body,"text"))throw new InvalidDataException("Restored raw document/text binding mismatch");}else b.AppendLine("Raw HTML отсутствует в этом каталоге/экспорте. Ниже сохранён нормализованный снимок с хешем; новая проверка raw-ответа сейчас не заявлена.");}else EvidenceBindings.Check(root,body,false);if(ProvenanceAudit.Sha(S(body,"text"))!=S(body,"text_sha256"))throw new InvalidDataException("Document text hash mismatch");b.AppendLine("Получено: "+EvidenceDates.Display(V(body,"captured_at"))+" | SHA256 текста: "+S(body,"text_sha256"));}else b.AppendLine("Есть только старые фрагменты коллектора. Полный текст/диапазон старого ответа не восстановлен; цена и текущая применимость не проверены.");foreach(var fragment in Items(doc,"saved_fragments")){var r=D(V(fragment,"literal_reference"));if(r.Count>0){if(body.Count==0||S(r,"text_sha256")!=S(body,"text_sha256")||ProvenanceAudit.Slice(S(body,"text"),Convert.ToInt32(V(r,"start")),Convert.ToInt32(V(r,"end")))!=S(r,"quote"))throw new InvalidDataException("Legacy review fragment mismatch");b.AppendLine("Буквально в указанном снимке ["+S(r,"start")+","+S(r,"end")+"): "+S(r,"quote"));}else b.AppendLine("НЕ ПЕРЕПРОВЕРЕННЫЙ старый фрагмент: "+S(fragment,"quote"));}if(S(doc,"legacy_error")!="")b.AppendLine("Историческая ошибка чтения: "+S(doc,"legacy_error")+"; не доказательство отсутствия правила/решения.");}
 return b.AppendLine("AUTO_ADMISSION=false. Старые записи и решения владельца не переписаны.").ToString();}catch(Exception ex){return "Ручной разбор недоступен для проверки: "+ex.Message+". Это не готовность/одобрение; исходный кандидат не изменён.\r\n";}}
}
